source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if grid[r][c] == grid[r][c + 1] == grid[r + 1][c] == grid[r + 1][c + 1] == 2:
                blocks.append((r, c))
    block_cells = {(r+dr, c+dc) for r,c in blocks for dr in (0,1) for dc in (0,1)}
    for r, c in blocks:
        positions = ((r-1,c-1,-1,-1), (r-1,c+2,-1,1), (r+2,c-1,1,-1), (r+2,c+2,1,1))
        coords = [(mr,mc) for mr,mc,_,_ in positions]
        vals = [grid[mr][mc] if 0 <= mr < h and 0 <= mc < w else 0 for mr,mc in coords]
        colors = [vals[2], vals[0], vals[3], vals[1]]
        for (mr,mc,dr,dc), color in zip(positions, colors):
            if not (0 <= mr < h and 0 <= mc < w) or grid[mr][mc] == 0:
                continue
            rr, cc = mr, mc
            while 0 <= rr < h and 0 <= cc < w and (rr,cc) not in block_cells:
                out[rr][cc] = color
                nr,nc=rr+dr,cc+dc
                nnr,nnc=nr+dr,nc+dc
                clipped=False
                for br,bc in blocks:
                    if (br,bc)==(r,c):
                        continue
                    # Do not continue along the side of another 2x2 block.
                    if (br <= nr <= br+1 and br <= nnr <= br+1 and (nc < bc or nc > bc+1) and (nnc < bc or nnc > bc+1)):
                        clipped=True
                    if (bc <= nc <= bc+1 and bc <= nnc <= bc+1 and (nr < br or nr > br+1) and (nnr < br or nnr > br+1)):
                        clipped=True
                if clipped:
                    break
                rr,cc=nr,nc
    return out
'''
